	border: none;
	border-radius: 50%;
	background: transparent;
	color: inherit;
	cursor: pointer;
	opacity: .75;
}
.gm-fm__chip-close svg[data-v-d5ecdb82] {
	display: block;
}
.gm-fm__chip-close[data-v-d5ecdb82]:hover {
