.gm-fm__loading[data-v-d5ecdb82] {
	display: flex;
	justify-content: center;
	padding: 20px 0;
}
.gm-fm__empty[data-v-d5ecdb82] {
	color: var(--color-text-maxcontrast);
}
.gm-fm__load-error[data-v-d5ecdb82] {
	display: flex;
	flex-direction: column;
	align-items: flex-start;
	gap: 8px;
}
.gm-fm__table[data-v-d5ecdb82] {
	display: flex;
	flex-direction: column;
}
.gm-fm__row[data-v-d5ecdb82] {
	display: flex;
	align-items: center;
	height: 40px;
	border-top: 1px solid var(--color-border);
}
.gm-fm__row--head[data-v-d5ecdb82] {
	height: auto;
	padding-bottom: 6px;
	border-top: none;
	font-size: 11px;
	font-weight: 700;
	text-transform: uppercase;
	letter-spacing: .07em;
