	gap: 4px;
	margin-top: 4px;
	padding-top: 4px;
	border-top: 1px solid var(--color-border);
}
.gm-fm__quota-custom-input[data-v-d5ecdb82] {
	flex: 1;
	min-width: 0;
	min-height: 0;
