		return {
			gid: '',
			displayName: '',
			errorMessage: '',
			fieldError: false,
		}
	},

	computed: {
		buttons() {
			return [
				{ label: t('group_manager', 'Cancel'), type: 'reset', callback: () => true },
				{
					label: t('group_manager', 'Create'),
					type: 'submit',
					variant: 'primary',
					callback: this.submit,
				},
			]
		},
	},

	methods: {
		t,

		onUpdateOpen(value) {
			this.$emit('update:open', value)
			if (!value) {
